    const elbow = {
      x: shoulder.x + Math.sin(a) * UPPER * fv,
      y: shoulder.y + Math.cos(a) * UPPER,
    };
    const hand = {
      x: elbow.x + Math.sin(a + e) * FORE * fv,
      y: elbow.y + Math.cos(a + e) * FORE,
    };
    return { elbow, hand };
