const CATEGORY_LABELS = {
  all: "All Shortcuts",
  global: "Global & System",
  desktop: "Desktop & Files",
  notepad: "Notepad",
  browser: "Yuki Browser",
  calc: "Calculator",
  calendar: "Calendar",
  terminal: "Terminal",
  office: "Office",
  games: "Games",
  steamdeck: "Yuki Deck",
  custom: "Custom",
};

function getCategoryLabel(cat) {
  return CATEGORY_LABELS[cat] || "Shortcuts";
}

function getItemId(shortcut) {
  return `sc-item-${shortcut.id.replace(/\./g, "-")}`;
}

function formatKeys(keys) {
  return keys
    .map((k) => {
      const lower = k.toLowerCase();
      if (lower === "ctrl" || lower === "control") return "Ctrl";
      if (lower === "shift") return "Shift";
      if (lower === "alt" || lower === "option") return "Alt";
      if (
        lower === "meta" ||
        lower === "cmd" ||
        lower === "command" ||
        lower === "super"
      )
        return "Cmd";
      if (k === "ArrowLeft") return "←";
      if (k === "ArrowRight") return "→";
      if (k === "ArrowUp") return "↑";
      if (k === "ArrowDown") return "↓";
      return k;
    })
    .join(" + ");
}

function getActionTypeLabel(type) {
  const labels = {
    launchApp: "Launch App",
    openUrl: "Open URL",
    runCode: "Run Code",
    notify: "Notify",
  };
  return labels[type] || type;
}

function getActionTypeIcon(type) {
  const icons = {
    launchApp: "fas fa-rocket",
    openUrl: "fas fa-link",
    runCode: "fas fa-code",
    notify: "fas fa-bell",
  };
  return icons[type] || "fas fa-star";
}

