class SteamAppRenderer extends GameWindowRenderer {
  getGames() {
    if (this.gamesCache) return this.gamesCache;
    const appRegistry = getAppRegistry();
    this.gamesCache = Object.entries(appMap)
      .filter(([id, data]) => {
        if (data.type === "system") return false;
        if (GAMES_APP_EXCLUDED.has(id)) return false;
        if (!data.icon || !data.title) return false;
        if (appRegistry.isAppUninstalled(id) || appRegistry.isAppDisabled(id))
          return false;
        return true;
      })
      .map(([id, data]) => ({ app: id, ...data }));
    return this.gamesCache;
  }
}

function handleGameUrlParam(renderer, container, onLaunch, wm = null) {
  renderer.render(container, onLaunch, wm);

  const urlParams = new URLSearchParams(window.location.search);
  const gameParam = urlParams.get("steam");
  if (!gameParam) return;

  const matchedGame = renderer.getGames().find((g) => g.app === gameParam);
  if (!matchedGame) return;

  setTimeout(() => {
    const sidebarEl = container.querySelector(".steam-library-sidebar");
    const libraryPageEl = container.querySelector(".steam-library-page");
    const storePageEl = container.querySelector(".steam-store-page");
    const communityPageEl = container.querySelector(".steam-community-page");
    const downloadsPageEl = container.querySelector(".steam-downloads-page");
    const tabEls = container.querySelectorAll(".steam-tab");

    [libraryPageEl, storePageEl, communityPageEl, downloadsPageEl].forEach(
      (p) => p && p.classList.add("hidden"),
    );
    tabEls.forEach((t) => t.classList.remove("active"));
    const libTab = container.querySelector(".steam-tab[data-page='library']");
    if (libTab) libTab.classList.add("active");
    if (libraryPageEl) libraryPageEl.classList.remove("hidden");
    if (sidebarEl) sidebarEl.classList.remove("hidden");

    renderer.renderGameOverview(container, gameParam, onLaunch);

    const sidebarItems = container.querySelectorAll(".sidebar-game-item");
    sidebarItems.forEach((item) => {
      item.classList.toggle("active", item.dataset.app === gameParam);
    });

    const activeItem = container.querySelector(
      `.sidebar-game-item[data-app="${gameParam}"]`,
    );
    if (activeItem) {
      activeItem.scrollIntoView({ behavior: "smooth", block: "nearest" });
    }
  }, 1600);
}

function createAppActions(appLauncher) {
  const actions = {};

  const LAUNCH_METHOD_DISPATCH = {
    openYukiDevToolsApp: (extra) => appLauncher.openYukiDevToolsApp(extra),
  };

  for (const [appId, metadata] of Object.entries(SYSTEM_APPS)) {
    const { launchType, source, title, launchMethod } = metadata;

    switch (launchType) {
      case "instance":
        actions[appId] = (extra) => {
          if (appId === "taskManagerApp") {
            const appInstance = appLauncher.taskManager;
            if (appInstance) return appInstance.open(extra);
            console.error(`No app instance found for ${appId}`);
            return;
          }

          const appInstance =
            appLauncher.appRegistry.get(appId) ||
            appLauncher[appId] ||
            appLauncher[appId + "App"];
          if (appInstance) return appInstance.open(extra);

          console.error(`No app instance found for ${appId}`);
        };
        break;

      case "method":
        actions[appId] = (extra) => {
          const dispatch = LAUNCH_METHOD_DISPATCH[launchMethod];
          if (launchMethod && dispatch) {
            return dispatch(extra);
          }
          console.error(`No launch method found for ${appId}`);
        };
        break;

      case "iframe":
        actions[appId] = () => {
          if (!source) {
            console.error(`No source URL defined for iframe app ${appId}`);
            return;
          }
          return appLauncher.openIframeApp({
            appId,
            type: "game",
            source,
            originalName: title,
          });
        };
        break;

      case "steam":
        actions[appId] = (extra) => {
          return openSteamWindow(
            appLauncher,
            appLauncher.explorerApp.wm,
            null,
            extra?.steamGameId,
            extra?.steamPage,
            {
              userId: extra?.steamUserId,
            },
          );
        };
        break;

      case "remote":
        actions[appId] = (extra) => {
          const url = source || metadata.url;
          if (!url) {
            console.error(`No remote URL defined for app ${appId}`);
            return;
          }
          return appLauncher.openRemoteApp(url);
        };
        break;

      default:
        console.warn(`Unknown launchType "${launchType}" for app ${appId}`);
    }
  }

  return actions;
}

