  circ(ctx, "fill", -s * 0.035, -thick(hp) * 0.3, s * 0.02);
  setColor(ctx, 1, 1, 1, 0.8);
  circ(ctx, "fill", -s * 0.045, -thick(hp) * 0.33, s * 0.008);
